async ({ workspace: { search, read }, git: { status, log } }) => {
  const [s1, s2, st, lg, contrib] = await Promise.all([
    search("pit", { regex: false, limit: 100, ignore: ["node_modules/**", "dist/**", "package-lock.json"] }),
    search("uses: ", { limit: 100, contextLines: 0 }),
    status(["--short", "--branch"]),
    log(["--oneline", "-10"]),
    search("version|VERSION|@v?[0-9]+\\.[0-9]+", { regex: true, limit: 200, contextLines: 0, ignore: ["node_modules/**", "dist/**", "package-lock.json", "CHANGELOG.md"] }),
  ]);
  const slim = (r:any) => r.matches?.map((m:any)=>`${m.file}:${m.line}: ${m.text}`) ?? r;
  return { s1: slim(s1), s2: slim(s2), st, lg, contrib: slim(contrib) };
}
